import{_ as e,o as l,c as a,ag as i}from"./chunks/framework.DXGyWiRo.js";const c=JSON.parse('{"title":"知识点5：信息系统基础","description":"","frontmatter":{"title":"知识点5：信息系统基础"},"headers":[],"relativePath":"high-school-it/knowledge-5.md","filePath":"high-school-it/knowledge-5.md"}'),r={name:"high-school-it/knowledge-5.md"};function n(o,t,d,s,h,p){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="知识点5-信息系统基础" tabindex="-1">知识点5：信息系统基础 <a class="header-anchor" href="#知识点5-信息系统基础" aria-label="Permalink to &quot;知识点5：信息系统基础&quot;">​</a></h1><h2 id="一、组成要素" tabindex="-1">一、组成要素 <a class="header-anchor" href="#一、组成要素" aria-label="Permalink to &quot;一、组成要素&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">要素</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:center;">硬件</td><td style="text-align:left;">物理设备</td><td style="text-align:left;">传感器、服务器、交换机</td></tr><tr><td style="text-align:center;">软件</td><td style="text-align:left;">程序与系统</td><td style="text-align:left;">操作系统、应用软件</td></tr><tr><td style="text-align:center;">数据</td><td style="text-align:left;">系统处理的对象</td><td style="text-align:left;">订餐记录、预约信息</td></tr><tr><td style="text-align:center;">人</td><td style="text-align:left;">使用者与管理者</td><td style="text-align:left;">管理员、用户</td></tr></tbody></table><h2 id="二、信息系统生命周期" tabindex="-1">二、信息系统生命周期 <a class="header-anchor" href="#二、信息系统生命周期" aria-label="Permalink to &quot;二、信息系统生命周期&quot;">​</a></h2><p>正确顺序：调研需求 → 分析功能模块 → 详细设计（数据库与界面）→ 搭建环境与编码 → 测试试运行</p><p>即：<strong>需求分析 → 系统设计 → 详细设计 → 编码实现 → 测试运行</strong></p><h2 id="三、信息系统运维" tabindex="-1">三、信息系统运维 <a class="header-anchor" href="#三、信息系统运维" aria-label="Permalink to &quot;三、信息系统运维&quot;">​</a></h2><p>管理员的运维职责：系统软件更新、用户密码重置、数据备份、服务器故障排查等。</p><hr><h2 id="四、真题" tabindex="-1">四、真题 <a class="header-anchor" href="#四、真题" aria-label="Permalink to &quot;四、真题&quot;">​</a></h2><p><strong>1.（2025-01，综合题二）</strong> 水质监测系统中的各种传感器属于信息系统组成要素中的（ ）（单选题，2分）</p><ul><li>A. 硬件</li><li>B. 数据</li><li>C. 网关</li><li>D. 软件</li></ul><p><strong>2.（浦东新区2025，综合题二）</strong> 小申定期从后台导出每周学生的订餐记录进行分析，这些订餐记录属于信息系统组成要素中的__________（选填：人/硬件/软件/数据）。（填空题，2分）</p><p><strong>3.（浦东新区2025，综合题二）</strong> 小申作为校园订餐系统的管理员，以下哪些属于他的运维工作职责？（ ）（多选题，3分）</p><ul><li>A. 系统软件更新</li><li>B. 用户密码重置</li><li>C. 订单数据备份</li><li>D. 服务器故障排查</li></ul><p><strong>4.（浦东新区2025，综合题三）</strong> 小申协助学校进行校园开放日预约系统的设计与开发，关于信息系统生命周期的一般步骤，正确的顺序是（ ）（单选题，2分）</p><p>① 对各功能模块进行详细设计，包括数据库设计与界面设计等</p><p>② 根据系统目标，分析并明确该系统需包含的具体功能模块</p><p>③ 调研学校各部门及家长的需求，明确系统目标并制定开发计划</p><p>④ 搭建软硬件开发环境，进行算法设计与编程实现</p><p>⑤ 完成系统开发后，对校园开放日预约系统开展测试与试运行</p><ul><li>A. ②①③④⑤</li><li>B. ③②①④⑤</li><li>C. ①②④⑤③</li><li>D. ③①②④⑤</li></ul><h3 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h3><ol><li>A</li><li>数据</li><li>ABCD</li><li>B（③调研需求 → ②分析功能 → ①详细设计 → ④编码实现 → ⑤测试运行）</li></ol>',24)])])}const _=e(r,[["render",n]]);export{c as __pageData,_ as default};
